def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    out = [row[:] for row in grid]

    colors = {v for row in grid for v in row if v != bg}
    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        for dr, dc in ((1, 1), (1, -1)):
            # A pair on a diagonal identifies the line to extend.
            if not any((r + dr, c + dc) in pts for r, c in pts):
                continue
            r, c = pts[0]
            while 0 <= r - dr < h and 0 <= c - dc < w:
                r, c = r - dr, c - dc
            while 0 <= r < h and 0 <= c < w:
                if out[r][c] == bg:
                    out[r][c] = color
                r += dr
                c += dc
    return out
